/**
 * NON-DESTRUCTIVE Beverly local transition patch seam experiments.
 * Bitsets computed from certified-appearance experimental clone 2026-11-04.
 * Only triangles in the separate SURG_BEVERLY__base001_1 patch are filtered.
 * The original GLB, skinned joint weights, body and attachment remain untouched.
 * Disabled by default: ?patchtrim=light or ?patchtrim=medium
 */
const REMOVE_BITS={
 light:"",
 medium:""
};
export function createBeverlyPatchTrim(model,THREE){
 const patch=model.getObjectByName('SURG_BEVERLY__base001_1');
 if(!patch?.isSkinnedMesh||!patch.geometry.getIndex()||patch.geometry.getIndex().count!==5924*3){
   return {available:false,reason:'Patch geometry signature mismatch'};
 }
 const original=patch.geometry,indices=Array.from(original.index.array),count=5924;
 let current='original',temporary=null;
 const set=(name)=>{
   if(temporary){patch.geometry=original;temporary.dispose();temporary=null}
   current='original';
   if(!REMOVE_BITS[name])return {name:'original',faces:count,removed:0};
   const binary=atob(REMOVE_BITS[name]);
   if(binary.length!==Math.ceil(count/8))
     throw new Error('Beverly patch mask length mismatch — preserving original');
   const newIndices=[];let removed=0;
   for(let face=0;face<count;face++){
     if(binary.charCodeAt(face>>3)&(1<<(face&7))){removed++;continue}
     const i=face*3;newIndices.push(indices[i],indices[i+1],indices[i+2]);
   }
   temporary=original.clone();
   temporary.setIndex(new THREE.BufferAttribute(new Uint32Array(newIndices),1));
   patch.geometry=temporary;
   current=name;
   return {name,faces:newIndices.length/3,removed};
 };
 return {available:true,set,restore:()=>set('original'),state:()=>({current,count,patchName:patch.name})};
}
